  let localities;
  const cache = new Map();

  function areaAndExchange(value) {
    const raw = String(value || '').trim();
    const primary = raw.split(';', 1)[0];
    if (primary.startsWith('+') && !primary.startsWith('+1')) return null;
    let digits = primary.replace(/\D/g, '');
    if (digits.length === 11 && digits.startsWith('1')) digits = digits.slice(1);
    return digits.length === 10 ? [digits.slice(0, 3), Number(digits.slice(3, 6))] : null;
  }

  function bytes(encoded) {
    const binary = atob(encoded);
    return Uint8Array.from(binary, character => character.charCodeAt(0));
  }

  function readVarint(data, cursor) {
    let value = 0;
    let shift = 0;
    while (cursor.index < data.length) {
      const byte = data[cursor.index++];
      value |= (byte & 0x7f) << shift;
      if ((byte & 0x80) === 0) return value;
      shift += 7;
    }
    return value;
  }

  function decodeArea(area) {
    if (cache.has(area)) return cache.get(area);
    const encoded = detail[area];
    if (!encoded) { cache.set(area, null); return null; }
    const data = bytes(encoded);
    const cursor = { index: 0 };
    const dominant = readVarint(data, cursor);
    const assigned = data.slice(cursor.index, cursor.index + 100);
    cursor.index += 100;
    const exceptions = new Map();
    const groupCount = readVarint(data, cursor);
    for (let group = 0; group < groupCount; group += 1) {
      const locality = readVarint(data, cursor);
      const count = readVarint(data, cursor);
      let exchange = -1;
      for (let item = 0; item < count; item += 1) {
        exchange += readVarint(data, cursor);
        exceptions.set(exchange + 200, locality);
      }
    }
    const decoded = Object.freeze({ dominant, assigned, exceptions });
    cache.set(area, decoded);
    return decoded;
  }

  function exactLocality(area, exchange) {
    const decoded = decodeArea(area);
    if (!decoded || exchange < 200 || exchange > 999) return '';
    const offset = exchange - 200;
    if ((decoded.assigned[offset >> 3] & (1 << (offset & 7))) === 0) return '';
    localities ||= localityText.split('\n');
    return localities[decoded.exceptions.get(exchange) ?? decoded.dominant] || '';
  }

  function lookup(value) {
    const parts = areaAndExchange(value);
    if (!parts) return '';
    const [area, exchange] = parts;
    const region = areas.get(area);
    if (!region) return '';
    const locality = exactLocality(area, exchange);
    return locality ? `${locality}, ${region}` : region;
  }

  Object.defineProperty(globalThis, KEY, {
    value: Object.freeze({ lookup }),
    configurable: true
  });
